INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich für Port 3306 Root-Rechte brauche?', 2, '[{"text": "Nein", "correct": true, "because": "Registrierte Ports benötigen keine Root-Rechte"}, {"text": "Ja", "correct": false, "because": "Normale Nutzer können sie nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Dienst nutzt standardmäßig Port 5060?', 3, '[{"text": "SIP", "correct": true, "because": "Für VoIP-Dienste registriert"}, {"text": "MySQL", "correct": false, "because": "Nutzt Port 3306"}, {"text": "HTTP", "correct": false, "because": "Nutzt Port 80"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Ports im Bereich 1024 bis 49151?', 5, '[{"text": "Von IANA zugeteilt", "correct": true, "because": "Für spezifische Dienste registriert"}, {"text": "Keine Root-Rechte nötig", "correct": true, "because": "Von normalen Nutzern nutzbar"}, {"text": "Dynamisch zugewiesen", "correct": false, "because": "Das sind Ports ab 49152"}, {"text": "Nur für Well-Known-Dienste", "correct": false, "because": "Das sind Ports 0-1023"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Port 8080 ist eine Alternative zu 80. b) Er ist ein Well-Known-Port.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "8080 ist kein Well-Known-Port"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Ports für meine Anwendung?', 4, '[{"text": "Portregistrierung", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Protokolltyp", "correct": false, "because": "TCP/UDP muss passen"}, {"text": "Betriebssystemfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Port 10000 für Webmin registriert ist?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für Webmin"}, {"text": "Nein", "correct": false, "because": "Von IANA zugeteilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Port wird oft für alternative Webserver genutzt?', 3, '[{"text": "8080", "correct": true, "because": "Häufig für Testzwecke"}, {"text": "21", "correct": false, "because": "Für FTP"}, {"text": "110", "correct": false, "because": "Für POP3"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Port 3306 nur für TCP ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "MySQL nutzt standardmäßig TCP"}, {"text": "Nein", "correct": false, "because": "UDP ist nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Port mehrfach registriert sein?', 2, '[{"text": "Ja", "correct": true, "because": "Mögliche Doppelbelegung"}, {"text": "Nein", "correct": false, "because": "Konflikte möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ports nutzen bekannte Datenbankdienste?', 4, '[{"text": "3306 für MySQL", "correct": true, "because": "Standardport"}, {"text": "1433 für MSSQL", "correct": true, "because": "Standardport"}, {"text": "80 für Web", "correct": false, "because": "Für HTTP"}, {"text": "5060 für VoIP", "correct": false, "because": "Für SIP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Portwahl für eine neue Anwendung?', 4, '[{"text": "Freien, registrierten Port", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Well-Known-Port", "correct": false, "because": "Für Standarddienste"}, {"text": "Zufälligen Port", "correct": false, "because": "Weniger vorhersehbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Port 5060 ist für VoIP. b) Er ist dynamisch zugeteilt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "5060 ist registriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Port für meinen Dienst zu wählen?', 3, '[{"text": "IANA-Registrierung", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Protokollkompatibilität", "correct": false, "because": "TCP/UDP entscheidend"}, {"text": "Firmenlogo", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen freien Port finde?', 4, '[{"text": "IANA-Liste prüfen", "correct": true, "because": "Zeigt belegte Ports"}, {"text": "Zufall auswählen", "correct": false, "because": "Risiko von Konflikten"}, {"text": "Port 80 nutzen", "correct": false, "because": "Für HTTP reserviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Port 1433 nur für MSSQL ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für MSSQL"}, {"text": "Nein", "correct": false, "because": "Primär für MSSQL registriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Portkonflikte zu vermeiden?', 3, '[{"text": "Registrierung bei IANA", "correct": true, "because": "Sichert eindeutige Zuordnung"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Risiko von Überschneidungen"}, {"text": "Hohe Portnummern", "correct": false, "because": "Nicht immer frei"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Port 8080 für normale Nutzer gesperrt?', 2, '[{"text": "Nein", "correct": true, "because": "Registrierte Ports sind offen"}, {"text": "Ja", "correct": false, "because": "Kein Root nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste nutzen Ports im Bereich 1024-49151?', 5, '[{"text": "MySQL", "correct": true, "because": "Port 3306"}, {"text": "SIP", "correct": true, "because": "Port 5060"}, {"text": "HTTP", "correct": false, "because": "Port 80"}, {"text": "FTP", "correct": false, "because": "Port 21"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung eines Ports für eine App unwichtig?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zum Protokoll passen"}, {"text": "Verfügbarkeit", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "App-Design", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Port für VoIP brauche?', 4, '[{"text": "Port 5060 wählen", "correct": true, "because": "Für SIP registriert"}, {"text": "Port 80 nutzen", "correct": false, "because": "Für HTTP"}, {"text": "Zufälligen Port", "correct": false, "because": "Nicht standardisiert"}]');
